// Xác định loại báo cáo theo giờ hiện tại
const now = new Date();
const hour = now.getHours();

let reportType = 'none';
if (hour === 8) reportType = 'morning';
else if (hour === 12) reportType = 'midday';
else if (hour === 17) reportType = 'eod';

if (reportType === 'none') {
  return [{ json: { skip: true, hour, reportType } }];
}

return [{ json: { skip: false, hour, reportType } }];

const items = $input.all();
const reportType = $('Kiểm Tra Giờ').item.json.reportType;
const now = new Date();
const timeStr = now.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

let rows = [];
try {
  rows = items.map(i => i.json).filter(r => r && !r.error);
} catch(e) {
  rows = [];
}

const reportTitles = {
  morning: '🌅 BÁO CÁO BUỔI SÁNG',
  midday: '🌞 BÁO CÁO GIỮA NGÀY',
  eod: '🌆 BÁO CÁO CUỐI NGÀY'
};

const title = reportTitles[reportType] || 'BÁO CÁO';

if (!rows.length) {
  return [{ json: {
    message: title + '\n' + timeStr + '\n\n✅ Không có dữ liệu cần xử lý.',
    reportType
  } }];
}

let msg = title + '\n' + timeStr + '\n\n';

if (reportType === 'morning') {
  msg += '📋 TỔNG QUAN HÔM NAY:\n';
  const total = rows.length;
  msg += `• Có ${total} mục cần chú ý hôm nay.\n`;
  rows.slice(0, 10).forEach((r, i) => {
    const line = Object.values(r).slice(0, 3).join(' | ');
    msg += `  ${i+1}. ${line}\n`;
  });
  if (total > 10) msg += `  ... và ${total - 10} mục khác.\n`;
} else {
  rows.slice(0, 5).forEach((r, i) => {
    const line = Object.entries(r).slice(0, 4).map(([k,v]) => `${k}: ${v}`).join(', ');
    msg += `${i+1}. ${line}\n`;
  });
}

return [{ json: { message: msg, reportType, count: rows.length } }];

const result = $input.item.json;
const report = $('Format Báo Cáo').item.json;
console.log('CronJob K5 completed:', report.reportType, '| Count:', report.count);
return [{ json: {
  status: 'done',
  reportType: report.reportType,
  count: report.count,
  telegram_ok: !result.error
} }];
